(() => {
  /* ---------- CONFIG ---------- */
  const SELECTORS = [
    // ICS Calendar list items (Upcoming events block generated by ICS)
    '.ics-calendar-list-wrapper .ics-calendar-date-wrapper',
    // Your front-page widget cards
    '.events-widget .event-card'
  ].join(',');

  const PARAM_KEY = 'r34icsym';     // ?r34icsym=YYYYMM
  const CALENDAR_SLUG = 'calendar'; // your calendar page slug

  /* ---------- HELPERS ---------- */
  const pad2 = n => (n < 10 ? '0' + n : '' + n);

  // Find site base from <link rel="home"> (fallback to origin)
  const getSiteBaseUrl = () => {
    try {
      const loc = new URL(location.href);
      const homeEl = document.querySelector('link[rel="home"]');
      if (homeEl?.href) {
        const homeURL = new URL(homeEl.href, loc);
        if (!homeURL.pathname.endsWith('/')) homeURL.pathname += '/';
        return homeURL.href;
      }
    } catch {}
    return `${location.origin}/`;
  };

  // Build /calendar/ absolute URL
  const getCalendarBaseUrl = () => {
    const base = getSiteBaseUrl();
    return new URL(`${CALENDAR_SLUG}/`, base).href;
  };

  const currentYM = () => {
    const d = new Date();
    return { y: d.getFullYear(), m: d.getMonth() + 1 };
  };

  const toYYYYMM = ({ y, m }) => `${y}${pad2(m)}`;

  // Try to read explicit data-ym="YYYYMM"
  const ymFromDataset = el => {
    const v = el.getAttribute('data-ym');
    if (!v || !/^\d{6}$/.test(v)) return null;
    const y = parseInt(v.slice(0, 4), 10);
    const m = parseInt(v.slice(4, 6), 10);
    if (m < 1 || m > 12) return null;
    return { y, m };
  };

  // Try to read <time datetime="...">
  const ymFromTime = el => {
    const t = el.querySelector('time[datetime]');
    if (!t) return null;
    const iso = t.getAttribute('datetime');
    if (!iso) return null;
    const d = new Date(iso);
    if (isNaN(d)) return null;
    return { y: d.getFullYear(), m: d.getMonth() + 1 };
  };

  // Try to read ICS h4 id like "...-20251005" -> 202510
  const ymFromICSId = el => {
    const h4 = el.querySelector('h4[id]');
    if (!h4) return null;
    const m = h4.id.match(/-(\d{6})\d{2}$/); // capture YYYYMM before DD
    if (!m) return null;
    const y = parseInt(m[1].slice(0, 4), 10);
    const mm = parseInt(m[1].slice(4, 6), 10);
    if (mm < 1 || mm > 12) return null;
    return { y, m: mm };
  };

  // Fallback: try to read the month label before the wrapper (ICS list view)
  const ymFromMonthLabel = el => {
    // Look for a nearby label like "October 2025"
    const label = el.closest('.ics-calendar')?.querySelector('.ics-calendar-label');
    const txt = label ? label.textContent.trim() : '';
    const m = txt.match(/([A-Za-z]+)\s+(\d{4})/);
    if (!m) return null;
    const year = parseInt(m[2], 10);
    const map = {jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,sept:9,oct:10,nov:11,dec:12};
    const month = map[m[1].toLowerCase()];
    if (!month) return null;
    return { y: year, m: month };
  };

  const getYM = el =>
    ymFromDataset(el) || ymFromTime(el) || ymFromICSId(el) || ymFromMonthLabel(el) || currentYM();

  const clickIsOnInteractive = e =>
    !!e.target.closest('a, button, input, textarea, select, [role="button"]');

  const buildMonthUrl = ({ y, m }) => {
    const base = getCalendarBaseUrl();
    const now = currentYM();
    // Current month: no param (clean URL)
    if (y === now.y && m === now.m) return base;
    const url = new URL(base);
    url.searchParams.set(PARAM_KEY, toYYYYMM({ y, m }));
    return url.href;
  };

  const navigate = (url, evt) => {
    if (evt && (evt.metaKey || evt.ctrlKey || evt.shiftKey || evt.altKey || evt.button === 1)) {
      window.open(url, '_blank', 'noopener');
    } else {
      location.assign(url);
    }
  };

  /* ---------- BIND ---------- */
  const install = el => {
    if (el._dsNavBound) return;
    el._dsNavBound = true;
    el.setAttribute('role', el.getAttribute('role') || 'link');
    if (!el.hasAttribute('tabindex')) el.setAttribute('tabindex', '0');
    el.style.cursor = el.style.cursor || 'pointer';

    const go = e => {
      if (clickIsOnInteractive(e)) return;
      const ym = getYM(el);
      const url = buildMonthUrl(ym);
      e.preventDefault();
      navigate(url, e);
    };

    el.addEventListener('click', go);
    el.addEventListener('auxclick', e => { if (e.button === 1) go(e); });
    el.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') go(e);
    });
  };

  const init = () => {
    document.querySelectorAll(SELECTORS).forEach(install);
  };

  // Initial + dynamic
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
  new MutationObserver(muts => {
    muts.forEach(m => {
      m.addedNodes.forEach(node => {
        if (!(node instanceof Element)) return;
        if (node.matches?.(SELECTORS)) install(node);
        node.querySelectorAll?.(SELECTORS).forEach(install);
      });
    });
  }).observe(document.body, { childList: true, subtree: true });
})();
